{
  "artifact_id": "LIVE-TEACH-CLAMP-functions",
  "revision": "r1",
  "task_id": "LIVE-TEACH-CLAMP",
  "task_revision": "t1",
  "type": "FunctionModel",
  "scope": "Proposed functional model for teaching and later test planning. Maps draft REQ01 retention and REQ02 damage prevention to candidate functions and interfaces. No requirements approval, concept selection, physical feasibility or test execution is established.",
  "conditions": [
    {
      "id": "C01",
      "text": "The task requests a bench clamp that holds a workpiece without damage. Input requirements REQ01 and REQ02 remain proposed; their hardness is unknown.",
      "kind": "fact",
      "evidence_refs": []
    },
    {
      "id": "C02",
      "text": "Customer loads, workpiece material, geometry, allowable movement and damage criteria are unknown.",
      "kind": "unknown",
      "evidence_refs": []
    },
    {
      "id": "C03",
      "text": "The functions, flows and scenarios below are modeling proposals. Necessity denotes their proposed contribution to the goal, not confirmed customer approval or physical feasibility.",
      "kind": "assumption",
      "evidence_refs": []
    },
    {
      "id": "C04",
      "text": "The supplied lunar-sampling case has unestablished transferability and supplies no clamp performance evidence or customer parameters.",
      "kind": "fact",
      "evidence_refs": [
        "case-98b73a9c96af1f9408721571"
      ]
    }
  ],
  "evidence_refs": [
    "case-98b73a9c96af1f9408721571"
  ],
  "payload": {
    "boundary": "Candidate functional boundary includes establishing workpiece contact, applying and maintaining restraint, managing contact effects, releasing restraint and assessing workpiece condition. External parties and objects are the operator or other actuation source, workpiece, bench/support and operation imposing loads; their characteristics remain unknown. Proposed normal path: establish contact, apply restraint, maintain restraint during work, release, assess condition. Proposed abnormal walkthroughs: workpiece slip, excessive contact effects, loss of actuation input and incomplete release. These are planning scenarios, not observed failures. Pause specification finalization and architecture freezing until use conditions and acceptance criteria are clarified.",
    "functions": [
      {
        "id": "F01",
        "verb_object": "Establish workpiece contact — proposed prerequisite for REQ01; accommodate the intended workpiece without selecting a jaw geometry or mechanism.",
        "necessity": "necessary",
        "evidence_refs": []
      },
      {
        "id": "F02",
        "verb_object": "Apply restraint — proposed contribution to REQ01; transform an unspecified actuation input into workpiece restraint.",
        "necessity": "necessary",
        "evidence_refs": []
      },
      {
        "id": "F03",
        "verb_object": "Maintain workpiece restraint — proposed contribution to REQ01 throughout the intended operation; required loads and duration remain unknown.",
        "necessity": "necessary",
        "evidence_refs": []
      },
      {
        "id": "F04",
        "verb_object": "Manage workpiece contact effects — proposed contribution to REQ02 during engagement, holding and release; acceptable effects remain undefined.",
        "necessity": "necessary",
        "evidence_refs": []
      },
      {
        "id": "F05",
        "verb_object": "Release workpiece restraint — proposed contribution to REQ02 during removal; release behavior and operator interaction require clarification.",
        "necessity": "necessary",
        "evidence_refs": []
      },
      {
        "id": "F06",
        "verb_object": "Assess workpiece condition — proposed supporting activity for later verification of REQ02; allocation to an operator or inspection resource is unresolved.",
        "necessity": "supporting",
        "evidence_refs": []
      }
    ],
    "flows": [
      {
        "id": "FL01",
        "from_function": "F02",
        "to_function": "F04",
        "flow_type": "energy",
        "description": "Proposed transfer of actuation work through the contact-management function during engagement. Input source, displacement, losses and magnitude are unknown; this does not establish a mechanism.",
        "evidence_refs": []
      },
      {
        "id": "FL02",
        "from_function": "F01",
        "to_function": "F02",
        "flow_type": "signal",
        "description": "Proposed information dependency: contact readiness permits restraint application. This may be an operator judgment; no sensor or automatic interlock is specified.",
        "evidence_refs": []
      },
      {
        "id": "FL03",
        "from_function": "F02",
        "to_function": "F03",
        "flow_type": "signal",
        "description": "Proposed information dependency: restraint establishment precedes the holding phase. How readiness is judged and what happens if it is uncertain remain unresolved.",
        "evidence_refs": []
      },
      {
        "id": "FL04",
        "from_function": "F05",
        "to_function": "F06",
        "flow_type": "material",
        "description": "Proposed handoff of the released workpiece for condition assessment. Inspection handling must itself be considered when defining damage assessment.",
        "evidence_refs": []
      }
    ],
    "interfaces": [
      {
        "id": "I01",
        "text": "Proposed workpiece interface: F01–F05 interact with the workpiece through contact and restraint. Material, finish, geometry, contact regions, force distribution, displacement and permitted surface changes are unknown. Interface owner and confirmation authority are unassigned. Proposed derived requirement: establish compatible contact conditions for retention and damage prevention before fixing a design.",
        "kind": "assumption",
        "evidence_refs": []
      },
      {
        "id": "I02",
        "text": "Proposed actuation interface: an external operator or other source supplies input to F02 and initiates F05. Input type, magnitude, units, travel, timing, feedback and behavior after input loss are unknown. Do not presume manual, powered or continuously energized actuation.",
        "kind": "assumption",
        "evidence_refs": []
      },
      {
        "id": "I03",
        "text": "Proposed support interface: F03 transfers reaction loads to a bench or other support. Attachment method, support stiffness, allowable movement and load directions are unknown. Later planning should define both clamp-side and support-side responsibilities and compatible limits.",
        "kind": "assumption",
        "evidence_refs": []
      },
      {
        "id": "I04",
        "text": "Proposed operation interface: the intended work operation imposes disturbances on the restrained workpiece. Load histories, durations, directions and interaction with release are unknown. Proposed derived requirement: define when work may begin and how slip or uncertain restraint should be handled.",
        "kind": "assumption",
        "evidence_refs": []
      },
      {
        "id": "I05",
        "text": "Proposed assessment interface: F06 receives the released workpiece and a pre-clamping condition record, and returns an assessment to the responsible reviewer. Inspection method, reference condition, acceptance limits, reviewer and record format remain unknown. This is a verification-planning dependency, not a specified built-in sensing function.",
        "kind": "assumption",
        "evidence_refs": []
      },
      {
        "id": "I06",
        "text": "Proposed verification plan: after stakeholders define representative workpieces, load conditions, allowable movement and damage criteria, plan retention observation and before/after condition assessment. Review engagement, holding, release and abnormal scenarios together. No procedure, threshold, sample count or acceptance result is established.",
        "kind": "assumption",
        "evidence_refs": []
      }
    ],
    "unknowns": [
      "Which work operation, operator capabilities and bench environment define the operating scenario?",
      "What workpiece materials, finishes, geometries and variations must be accommodated?",
      "What loads, directions, durations and allowable movements define retention?",
      "What constitutes damage during engagement, holding, release and inspection?",
      "Can retention and damage prevention be achieved together under the eventual use conditions?",
      "What actuation source, support interface and release behavior are required?",
      "What are the consequences and required responses for slip, excessive contact effects, input loss or incomplete release?",
      "Who owns and confirms each requirement and interface, and which constraints are hard? Hardness remains unknown.",
      "How should functions be allocated among clamp, operator and external assessment resources? No physical architecture is selected.",
      "What verification resources and representative workpieces will be available? All verification described here remains a plan."
    ]
  }
}
